        // Функция для предсказания результата на основе входных данных
        public static double Predict(double[] inputs)
        {
            if (inputs.Length != 35)
                throw new InvalidFeatureVectorException($"Ожидалось 35 входных значений (7 непрерывных + 28 категориальных), получено {inputs.Length}");

            double[] dummy = CreateInputs(inputs);  // Преобразуем входные данные в нужный формат
            double result = PredictValue(dummy);    // Получаем предсказание
            return result;
        }

        // Создание входных данных для модели (аналог create_inputs в C)
        private static double[] CreateInputs(double[] input)
        {
            double[] dummy = new double[FeatureCount];  // 63 элемента

            // 1. Непрерывные переменные (первые 7) - нормализация
            for (int i = 0; i < 7; i++)
            {
                dummy[i] = ishift[i] + iscale[i] * input[i];
            }

            // 2. Категориальные переменные (28 переменных) - one-hot encoding
            int k = 0;  // индекс в InputNominals
            int dummyIndex = 7;  // начинаем с позиции 7 в dummy массиве

            for (int i = 0; i < 28; i++)  // 28 категориальных переменных
            {
                double inputValue = input[7 + i];  // значение i-й категориальной переменной

                // Для каждой категориальной переменной создаем 2 dummy-признака
                for (int j = 0; j < 2; j++)  // у всех по 2 категории
                {
                    if (inputValue == InputNominals[k])
                        dummy[dummyIndex] = 1.0;
                    else
                        dummy[dummyIndex] = 0.0;

                    k++;
                    dummyIndex++;
                }
            }

            return dummy;
        }

        // Функция ядра (kernel) - линейное ядро
        private static double Kernel(double[] dummy, int svIndex)
        {
            double sum = 0;
            int startIndex = svIndex * FeatureCount;

            // Скалярное произведение вектора dummy и опорного вектора
            for (int i = 0; i < FeatureCount; i++)
            {
                sum += dummy[i] * SV[startIndex + i];
            }

            return sum;
        }

        // Функция для расчета предсказания
        private static double PredictValue(double[] dummy)
        {
            if (dummy.Length != FeatureCount)
                throw new InvalidFeatureVectorException($"Ожидалось {FeatureCount} признаков, получено {dummy.Length}");

            double sum = 0;

            // Суммируем взвешенные ядерные функции
            for (int i = 0; i < 18; i++)  // 18 опорных векторов
            {
                sum += coefficients[i] * Kernel(dummy, i);
            }

            // Вычитаем константу
            sum -= constants[0];

            return sum;
        }

