        private static double[] GetWeights()
        {
            double[] w = new double[FeatureCount];

            for (int svIndex = 0; svIndex < coefficients.Length; svIndex++)
            {
                int startIndex = svIndex * FeatureCount;
                double coeff = coefficients[svIndex];

                for (int j = 0; j < FeatureCount; j++)
                {
                    w[j] += coeff * SV[startIndex + j];
                }
            }

            return w;
        }

        public static void GetTopRiskFactors(double[] inputs, int topN, out string[] names, out double[] values)
        {
            double[] dummy = CreateInputs(inputs);
            double[] w = GetWeights();

            double[] contributions = new double[35];

            // Первые 7 признаков
            for (int i = 0; i < 7; i++)
                contributions[i] = w[i] * dummy[i];

            int dummyIndex = 7;

            // Остальные 28 категориальных признаков
            for (int i = 7; i < 35; i++)
            {
                contributions[i] =
                    w[dummyIndex] * dummy[dummyIndex] +
                    w[dummyIndex + 1] * dummy[dummyIndex + 1];

                dummyIndex += 2;
            }

            // Оставляем только реально положительные вклады
            double epsilon = 1e-4;

            var selected = new List<int>();

            for (int i = 0; i < contributions.Length; i++)
            {
                if (contributions[i] > epsilon)
                    selected.Add(i);
            }

            selected = selected
                .OrderByDescending(i => contributions[i])
                .Take(topN)
                .ToList();

            names = new string[selected.Count];
            values = new double[selected.Count];

            for (int i = 0; i < selected.Count; i++)
            {
                names[i] = OriginalFeatureNames[selected[i]];
                values[i] = contributions[selected[i]];
            }
        }
    }
